/**
 * DevFlow Notification Service
 * Stores and manages in-app notifications generated by automation rules.
 */

import { APPWRITE_CONFIG, ID, Query } from '../config/appwrite';
import { dbAdapter } from './dbAdapter';
import { buildNotificationPermissions } from '../utils/permissions';
import { NOTIFICATION_TYPES } from '../config/constants';

const TABLE_NOTIFICATIONS = APPWRITE_CONFIG.tables.notifications;

export const notificationService = {
  /**
   * List notifications for a user.
   * @param {string} userId
   * @param {number} [limit=50]
   */
  async listNotifications(userId, limit = 50) {
    if (!userId) return [];

    try {
      const queries = [
        Query.equal('userId', userId),
        Query.orderDesc('$createdAt'),
        Query.limit(limit),
      ];

      const res = await dbAdapter.list(TABLE_NOTIFICATIONS, queries);
      return res.items;
    } catch (err) {
      console.warn('Failed to fetch notifications:', err.message);
      return [];
    }
  },

  /**
   * Create a new notification for a user.
   * @param {object} params
   * @param {string} params.userId
   * @param {string} params.title
   * @param {string} params.message
   * @param {string} [params.type='info']
   * @param {string} [params.link='']
   */
  async createNotification({ userId, title, message, type = NOTIFICATION_TYPES.INFO, link = '' }) {
    if (!userId || !title || !message) {
      throw new Error('userId, title, and message are required.');
    }

    const notificationId = ID.unique();
    const permissions = buildNotificationPermissions(userId);

    const payload = {
      userId,
      title: title.trim(),
      message: message.trim(),
      type: Object.values(NOTIFICATION_TYPES).includes(type) ? type : NOTIFICATION_TYPES.INFO,
      isRead: false,
      link: link || '',
    };

    return await dbAdapter.create(TABLE_NOTIFICATIONS, notificationId, payload, permissions);
  },

  /**
   * Mark a notification as read.
   * @param {string} notificationId
   */
  async markAsRead(notificationId) {
    if (!notificationId) return null;
    return await dbAdapter.update(TABLE_NOTIFICATIONS, notificationId, { isRead: true });
  },

  /**
   * Mark all unread notifications for a user as read.
   * @param {string} userId
   * @param {Array} currentNotifications
   */
  async markAllAsRead(userId, currentNotifications = []) {
    if (!userId) return;

    const unread = currentNotifications.filter((n) => !n.isRead);
    await Promise.allSettled(
      unread.map((n) => dbAdapter.update(TABLE_NOTIFICATIONS, n.$id, { isRead: true }))
    );
  },

  /**
   * Delete a notification.
   * @param {string} notificationId
   */
  async deleteNotification(notificationId) {
    if (!notificationId) return;
    return await dbAdapter.delete(TABLE_NOTIFICATIONS, notificationId);
  },
};
